# cogs/errors.pyimport loggingimport tracebackimport discordfrom discord.ext import commandslogger = logging.getLogger(__name__)class ErrorCog(commands.Cog):    """Global error handler for all commands."""    def __init__(self, bot: commands.Bot):        self.bot = bot        # Optional: set a channel ID to log errors to Discord        self.error_channel_id = 610696314476429313  # e.g., 1234567890123456789    async def send_error_log(self, title: str, content: str):        """Log error to console and optional Discord channel."""        logger.error(f"{title}\n{content}")        if self.error_channel_id:            try:                channel = self.bot.get_channel(self.error_channel_id)                if channel and isinstance(channel, discord.TextChannel):                    embed = discord.Embed(                        title=title,                        description=content[:1024],  # Discord limit                        color=discord.Color.red()                    )                    await channel.send(embed=embed)            except Exception as e:                logger.warning(f"Failed to send error to Discord: {e}")    @commands.Cog.listener()    async def on_command_error(self, ctx: commands.Context, error: commands.CommandError):        """Handle prefix command errors."""        if isinstance(error, commands.CommandNotFound):            return        if isinstance(error, commands.MissingPermissions):            await ctx.send("⛔ You don't have permission to run this command.", delete_after=10)            return        if isinstance(error, commands.CommandInvokeError):            error = error.original        tb = "".join(traceback.format_exception(type(error), error, error.__traceback__))        await self.send_error_log(            f"❌ Command Error: `{ctx.command}`",            f"User: {ctx.author}\nGuild: {ctx.guild}\n\n```py\n{tb}\n```"        )        await ctx.send(            f"⚠️ An error occurred: `{type(error).__name__}`. "            "The incident has been logged.",            delete_after=15        )    @commands.Cog.listener()    async def on_app_command_error(self, interaction: discord.Interaction, error: discord.app_commands.AppCommandError):        """Handle slash command errors."""        if isinstance(error, discord.app_commands.CommandOnCooldown):            await interaction.response.send_message(                f"⏳ Please wait {error.retry_after:.1f}s before using this again.",                ephemeral=True            )            return        if isinstance(error, discord.app_commands.MissingPermissions):            await interaction.response.send_message(                "⛔ You don't have permission to run this command.",                ephemeral=True,                delete_after=10            )            return        tb = "".join(traceback.format_exception(type(error), error, error.__traceback__))        user = interaction.user        guild = interaction.guild        cmd = interaction.command.name if interaction.command else "unknown"        await self.send_error_log(            f"❌ Slash Command Error: `{cmd}`",            f"User: {user}\nGuild: {guild}\n\n```py\n{tb}\n```"        )        try:            if interaction.response.is_done():                await interaction.followup.send(                    "⚠️ An error occurred. The incident has been logged.",                    ephemeral=True                )            else:                await interaction.response.send_message(                    "⚠️ An error occurred. The incident has been logged.",                    ephemeral=True                )        except discord.NotFound:            passasync def setup(bot: commands.Bot):    await bot.add_cog(ErrorCog(bot))